entries[140671] = { ["name"] = "Verschwinden", ["text"] = "Unbegrenzte Reichweite\nSofort\nErmöglicht es Euch, sofort zu verschwinden und Euch 3 Sek. lang in einem verbesserten Verstohlenheitsmodus zu bewegen. Die ersten 3 Sek. nach dem Verschwinden können weder Schaden noch schädliche Effekte die Verstohlenheit brechen. Bewegungseinschränkende Effekte werden beim Verschwinden entfernt." }
